package test;

import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.FontMetrics;

class ITextViewer { }
class Control { }
class StyledText {
    public int getLeftMargin() { return 10; }
}
class GC {
    public FontMetrics getFontMetrics() { return new FontMetrics(); }
    public void dispose() {}
}
class FontMetrics {
    public double getAverageCharacterWidth() { return 7.0; }
}

public class MyClass {
    private StyledText fTextWidget;
    private int fMarginWidth;
    private double fCachedWidgetX;

    public MyClass() {
        fTextWidget = new StyledText();
        fMarginWidth = 5;
    }

    public void calculateMargin(GC gc) {
        double pixels = gc.getFontMetrics().getAverageCharacterWidth();
        gc.dispose();
        fCachedWidgetX = (int) (pixels * fMarginWidth + 0.5);
    }
}

